def report(conn):
    orders = {}
    for oid, item in conn.execute("SELECT order_id, item FROM order_lines"):
        orders.setdefault(oid, set()).add(item)
    counts = {}
    for items in orders.values():
        for a, b in combinations(sorted(items), 2):
